function Get-PropertyValue {
    param(
        [object]$Object,
        [string[]]$Names
    )

    if ($null -eq $Object) {
        return $null
    }

    foreach ($name in $Names) {
        if ($Object -is [System.Collections.IDictionary]) {
            if ($Object.Contains($name)) {
                return $Object[$name]
            }
        }

        $property = $Object.PSObject.Properties[$name]

        if ($null -ne $property) {
            return $property.Value
        }
    }

    return $null
}

function Get-Items {
    param([object]$Body)

    $items = Get-PropertyValue -Object $Body -Names @("items")

    if ($null -eq $items) {
        return @()
    }

    return @($items)
}

function Invoke-ApiRequest {
    param(
        [ValidateSet("GET", "POST", "PUT", "PATCH", "DELETE")]
        [string]$Method,
        [string]$Uri,
        [hashtable]$Headers,
        [object]$Body = $null
    )

    $request = @{
        Uri         = $Uri
        Method      = $Method
        Headers     = $Headers
        ErrorAction = "Stop"
    }

    if ($null -ne $Body) {
        $request.ContentType = "application/json"

        if ($Body -is [string]) {
            $request.Body = $Body
        }
        else {
            $request.Body = $Body | ConvertTo-Json -Depth 20 -Compress
        }
    }

    try {
        $response = Invoke-WebRequest @request
        $raw = [string]$response.Content
        $parsed = $null

        if (-not [string]::IsNullOrWhiteSpace($raw)) {
            try {
                $parsed = $raw | ConvertFrom-Json
            }
            catch {
                $parsed = $null
            }
        }

        return [pscustomobject]@{
            StatusCode = [int]$response.StatusCode
            Body       = $parsed
            Raw        = $raw
            Error      = $null
        }
    }
    catch {
        $exception = $_.Exception
        $errorResponse = $exception.Response
        $statusCode = 0
        $raw = $exception.Message

        if ($null -ne $errorResponse) {
            try {
                $statusCode = [int]$errorResponse.StatusCode
            }
            catch {
                $statusCode = 0
            }

            try {
                $raw = $errorResponse.Content.ReadAsStringAsync().Result
            }
            catch {
                try {
                    $raw = $errorResponse.StatusDescription
                }
                catch {
                    $raw = $exception.Message
                }
            }
        }

        $parsed = $null

        if (-not [string]::IsNullOrWhiteSpace($raw)) {
            try {
                $parsed = $raw | ConvertFrom-Json
            }
            catch {
                $parsed = $null
            }
        }

        return [pscustomobject]@{
            StatusCode = $statusCode
            Body       = $parsed
            Raw        = $raw
            Error      = $exception.Message
        }
    }
}

function Assert-TestResult {
    param(
        [string]$Name,
        [object]$Response,
        [int[]]$ExpectedStatus = @(200),
        [scriptblock]$Condition = $null
    )

    $script:Total++
    $passed = $false
    $reason = "No response"

    if ($null -ne $Response) {
        $passed = $ExpectedStatus -contains [int]$Response.StatusCode
        $reason = "HTTP $($Response.StatusCode)"

        if ($passed -and $null -ne $Condition) {
            try {
                $passed = [bool](& $Condition $Response.Body)

                if (-not $passed) {
                    $reason = "$reason; response validation failed"
                }
            }
            catch {
                $passed = $false
                $reason = "$reason; validation error: $($_.Exception.Message)"
            }
        }

        if (-not $passed -and -not [string]::IsNullOrWhiteSpace($Response.Raw)) {
            $shortBody = $Response.Raw.Replace("`r", " ").Replace("`n", " ")

            if ($shortBody.Length -gt 300) {
                $shortBody = $shortBody.Substring(0, 300)
            }

            $reason = "$reason; $shortBody"
        }
    }

    if ($passed) {
        Write-Host "[PASS] $Name - $reason" -ForegroundColor Green
    }
    else {
        Write-Host "[FAIL] $Name - $reason" -ForegroundColor Red
        $script:Failures++

        if ($Strict) {
            throw "Strict mode stopped after failure: $Name"
        }
    }

    return $passed
}

function Write-SkippedTest {
    param([string]$Name)

    Write-Host "[SKIP] $Name" -ForegroundColor Yellow
}

function Wait-ForElasticsearchDocument {
    param(
        [string]$DocumentId,
        [int]$TimeoutSeconds = 20
    )

    $encodedId = [uri]::EscapeDataString($DocumentId)
    $uri = "$ElasticsearchUrl/$ElasticsearchIndex/$encodedId"
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    $lastResponse = $null

    do {
        $lastResponse = Invoke-ApiRequest `
            -Method GET `
            -Uri $uri `
            -Headers $elasticsearchHeaders

        if ($lastResponse.StatusCode -eq 200) {
            return $lastResponse
        }

        Start-Sleep -Seconds 1
    }
    while ((Get-Date) -lt $deadline)

    return $lastResponse
}

Write-Host ""
