$mapping = Invoke-ApiRequest `
    -Method GET `
    -Uri "$ElasticsearchUrl/$ElasticsearchIndex/_mapping" `
    -Headers $elasticsearchHeaders

$mappingEntry = Get-PropertyValue `
    -Object $mapping.Body `
    -Names @($ElasticsearchIndex)

$mappingsObject = Get-PropertyValue `
    -Object $mappingEntry `
    -Names @("mappings")

$mappingProperties = Get-PropertyValue `
    -Object $mappingsObject `
    -Names @("properties")

$requiredFields = @(
    "payment_id",
    "merchant_id",
    "customer_id",
    "order_id",
    "status",
    "amount_minor",
    "updated_at"
)

$missingFields = @()

foreach ($field in $requiredFields) {
    if ($null -eq (Get-PropertyValue $mappingProperties @($field))) {
        $missingFields += $field
    }
}

$mappingIsValid = $missingFields.Count -eq 0

Assert-TestResult `
    -Name "Payment index contains required mappings" `
    -Response $mapping `
    -ExpectedStatus @(200) `
    -Condition {
        param($body)
        $mappingIsValid
    }

