    -Response $countResponse `
    -ExpectedStatus @(200) `
    -Condition {
        param($body)
        $null -ne (Get-PropertyValue $body @("count"))
    }

if (-not [string]::IsNullOrWhiteSpace($CreatePaymentJsonPath)) {
    if (-not (Test-Path -LiteralPath $CreatePaymentJsonPath)) {
        Write-Host "[FAIL] Create payment JSON file was not found: $CreatePaymentJsonPath" `
            -ForegroundColor Red
        $script:Failures++
    }
    else {
        try {
            $createPayload = Get-Content `
                -LiteralPath $CreatePaymentJsonPath `
                -Raw `
                | ConvertFrom-Json

            $createResponse = Invoke-ApiRequest `
                -Method POST `
                -Uri "$PaymentBaseUrl$CreateEndpoint" `
                -Headers $paymentHeaders `
                -Body $createPayload

            Assert-TestResult `
                -Name "Create payment API request" `
                -Response $createResponse `
                -ExpectedStatus @(200, 201, 202)

            $createdObject = Get-PropertyValue `
                -Object $createResponse.Body `
                -Names @("payment", "data")

            $createdId = Get-PropertyValue `
                -Object $createResponse.Body `
                -Names @("payment_id", "id")

            if ($null -eq $createdId -and $null -ne $createdObject) {
                $createdId = Get-PropertyValue `
                    -Object $createdObject `
                    -Names @("payment_id", "id")
            }

            if ($null -ne $createdId) {
                $PaymentId = [string]$createdId
                Write-Host "Created payment ID: $PaymentId" -ForegroundColor Cyan

                $indexedResponse = Wait-ForElasticsearchDocument `
                    -DocumentId $PaymentId

                Assert-TestResult `
                    -Name "Created payment appears in Elasticsearch" `
                    -Response $indexedResponse `
                    -ExpectedStatus @(200) `
                    -Condition {
                        param($body)
                        $source = Get-PropertyValue $body @("_source")
                        $indexedId = Get-PropertyValue $source @("payment_id")
                        [string]$indexedId -eq [string]$PaymentId
                    }
            }
            else {
                Write-Host "[WARN] Create response did not contain payment_id or id" `
                    -ForegroundColor Yellow
            }
        }
        catch {
            Write-Host "[FAIL] Create payment payload could not be loaded: $($_.Exception.Message)" `
                -ForegroundColor Red
            $script:Failures++
        }
    }
}

$directSearchBody = @{
    size  = 5
    query = @{
        match_all = @{}
    }
    sort  = @(
        @{
            updated_at = @{
                order   = "desc"
                missing = "_last"
            }
        }
    )
}

$directSearch = Invoke-ApiRequest `
    -Method POST `
    -Uri "$ElasticsearchUrl/$ElasticsearchIndex/_search" `
    -Headers $elasticsearchHeaders `
    -Body $directSearchBody

Assert-TestResult `
    -Name "Direct Elasticsearch payment search" `
    -Response $directSearch `
    -ExpectedStatus @(200) `
    -Condition {
        param($body)
        $hits = Get-PropertyValue $body @("hits")
        $null -ne (Get-PropertyValue $hits @("hits"))
    }

$directHitsObject = Get-PropertyValue `
    -Object $directSearch.Body `
    -Names @("hits")

$directHitsValue = Get-PropertyValue `
