    -Names @("hits")

$directHits = if ($null -eq $directHitsValue) {
    @()
}
else {
    @($directHitsValue)
}

$observedId = $PaymentId

if ([string]::IsNullOrWhiteSpace($observedId)) {
    foreach ($hit in $directHits) {
        $source = Get-PropertyValue $hit @("_source")
        $candidateId = Get-PropertyValue $source @("payment_id", "id")

        if ($null -ne $candidateId) {
            $observedId = [string]$candidateId
            break
        }
    }
}

$appSearch = Invoke-ApiRequest `
    -Method GET `
    -Uri "$PaymentBaseUrl/api/v1/payments/search?page=1&size=5" `
