        param($body)
        $hasItems = $null -ne (Get-PropertyValue $body @("items"))
        $hasTotal = $null -ne (Get-PropertyValue $body @("total"))
        $hasItems -and $hasTotal
    }

if ($null -eq $observedId -and $appSearchItems.Count -gt 0) {
    $firstItemId = Get-PropertyValue `
        -Object $appSearchItems[0] `
        -Names @("payment_id", "id")

    if ($null -ne $firstItemId) {
        $observedId = [string]$firstItemId
    }
}

$paginationSearch = Invoke-ApiRequest `
