    -Headers $paymentHeaders

$paginationBody = $paginationSearch.Body
$paginationPage = Get-PropertyValue $paginationBody @("page")
$paginationSize = Get-PropertyValue $paginationBody @("size")
$paginationItems = Get-Items $paginationBody

$paginationIsValid = (
    [int]$paginationPage -eq 1 -and
    [int]$paginationSize -eq 1 -and
    $paginationItems.Count -le 1
)

Assert-TestResult `
    -Name "Application search pagination" `
    -Response $paginationSearch `
    -ExpectedStatus @(200) `
    -Condition {
        param($body)
        $paginationIsValid
    }

if (-not [string]::IsNullOrWhiteSpace($Status)) {
    $encodedStatus = [uri]::EscapeDataString($Status)
    $statusSearch = Invoke-ApiRequest `
