        -Headers $paymentHeaders

    $statusItems = Get-Items $statusSearch.Body
    $statusFilterIsValid = $true

    foreach ($item in $statusItems) {
        $itemStatus = Get-PropertyValue $item @("status")

        if ([string]$itemStatus -ne $Status) {
            $statusFilterIsValid = $false
        }
    }

    Assert-TestResult `
