if (-not [string]::IsNullOrWhiteSpace($observedId)) {
    $encodedPaymentId = [uri]::EscapeDataString($observedId)

    $querySearch = Invoke-ApiRequest `
        -Method GET `
        -Uri "$PaymentBaseUrl/api/v1/payments/search?q=$encodedPaymentId&page=1&size=20" `
        -Headers $paymentHeaders

    $queryItems = Get-Items $querySearch.Body
    $queryFoundId = $false

    foreach ($item in $queryItems) {
        $itemId = Get-PropertyValue $item @("payment_id", "id")

        if ([string]$itemId -eq [string]$observedId) {
            $queryFoundId = $true
        }
    }

    Assert-TestResult `
        -Name "Search by payment ID: $observedId" `
        -Response $querySearch `
        -ExpectedStatus @(200) `
        -Condition {
            param($body)
            $queryFoundId
        }

    $singlePayment = Invoke-ApiRequest `
        -Method GET `
        -Uri "$PaymentBaseUrl/api/v1/payments/$encodedPaymentId" `
        -Headers $paymentHeaders

    Assert-TestResult `
        -Name "Fetch payment by ID: $observedId" `
        -Response $singlePayment `
        -ExpectedStatus @(200) `
        -Condition {
            param($body)
            $returnedId = Get-PropertyValue $body @("payment_id", "id")
            [string]$returnedId -eq [string]$observedId
        }

    $esDocument = Invoke-ApiRequest `
        -Method GET `
        -Uri "$ElasticsearchUrl/$ElasticsearchIndex/$encodedPaymentId" `
        -Headers $elasticsearchHeaders

    Assert-TestResult `
        -Name "Fetch payment document directly from Elasticsearch" `
        -Response $esDocument `
        -ExpectedStatus @(200) `
        -Condition {
            param($body)
            $source = Get-PropertyValue $body @("_source")
            $indexedId = Get-PropertyValue $source @("payment_id")
            [string]$indexedId -eq [string]$observedId
        }
}
else {
    Write-SkippedTest `
        -Name "Payment-specific tests; provide -PaymentId or -CreatePaymentJsonPath"
}

if (-not $SkipNegativeTests) {
    $missingQuery = "not-found-$([guid]::NewGuid().ToString("N"))"
    $encodedMissingQuery = [uri]::EscapeDataString($missingQuery)

    $missingSearch = Invoke-ApiRequest `
        -Method GET `
        -Uri "$PaymentBaseUrl/api/v1/payments/search?q=$encodedMissingQuery&page=1&size=20" `
        -Headers $paymentHeaders

    $missingTotal = Get-PropertyValue $missingSearch.Body @("total")
    $missingSearchIsValid = (
        $missingSearch.StatusCode -eq 200 -and
        [int]$missingTotal -eq 0
    )

    Assert-TestResult `
        -Name "Search returns no result for unknown payment" `
        -Response $missingSearch `
        -ExpectedStatus @(200) `
        -Condition {
            param($body)
            $missingSearchIsValid
        }

    $invalidPagination = Invoke-ApiRequest `
        -Method GET `
        -Uri "$PaymentBaseUrl/api/v1/payments/search?page=0&size=0" `
        -Headers $paymentHeaders

    Assert-TestResult `
        -Name "Invalid pagination is rejected" `
        -Response $invalidPagination `
        -ExpectedStatus @(400, 422)
}

if ($null -ne $beforeCount -and -not [string]::IsNullOrWhiteSpace($PaymentId)) {
    $afterCountResponse = Invoke-ApiRequest `
        -Method GET `
        -Uri "$ElasticsearchUrl/$ElasticsearchIndex/_count" `
        -Headers $elasticsearchHeaders

    $afterCount = Get-PropertyValue `
