        -Names @("count")

    if ($null -ne $afterCount) {
        Assert-TestResult `
            -Name "Elasticsearch count remains readable after tests" `
            -Response $afterCountResponse `
            -ExpectedStatus @(200) `
            -Condition {
                param($body)
                $null -ne (Get-PropertyValue $body @("count"))
            }
    }
}

